  inset-inline: calc(-1 * var(--v4-menu-pad, var(--v4-space-3)));
  top: var(--v4-menu-pad, var(--v4-space-3));
  height: var(--v4-size-control-border);
  background-color: var(--v4-line-soft);
}
.empty {
  padding: var(--v4-space-16) var(--v4-space-8);
  color: var(--v4-muted);
  text-align: center;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--v4-space-4);
  padding: var(--v4-space-4);
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.hints {
  container-type: inline-size;
  display: flex;
  align-items: center;
  gap: var(--v4-space-12);
  min-height: var(--v4-size-control-lg);
  padding: 0 var(--v4-space-12);
  background-color: var(--v4-tint);
  overflow: hidden;
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
  color: var(--v4-muted);
  white-space: nowrap;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.hint {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--v4-space-4);
}
.hintsExtra {
  min-width: 0;
  margin-inline-start: auto;
  overflow: hidden;
  text-overflow: ellipsis;
}
@container (max-width: 360px) {
  .hint:nth-child(n + 2) {
    display: none;
  }
}
@container (max-width: 200px) {
  .hint {
    display: none;
  }
}

.mono {
  font-family: var(--v4-font-mono, monospace);
}
.error {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-bad, var(--destructive));
  padding: var(--v4-space-8) var(--v4-space-12);
}
.chips {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--v4-space-4);
}
.commandSearch {
  display: flex;
  align-items: center;
  gap: var(--v4-space-4);
  padding-inline-end: var(--v4-space-menu-inset);
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.commandSearch > [data-slot="command-input-wrapper"] {
  flex: 1;
  min-width: 0;
  border-bottom: 0;
}
.commandSearch > [data-v4-button] + [data-slot="command-input-wrapper"] {
  padding-inline-start: 0;
}
.commandSearch > [data-v4-button]:first-child {
  margin-inline-start: var(--v4-space-menu-inset);
}
.multiCombobox > [data-slot="multi-select"] {
  flex: 1 1 120px;
  width: auto;
}
.multiCombobox
  > [data-slot="multi-select"]:is(*, :focus-visible, [aria-expanded], [aria-invalid])[data-slot] {
  min-height: var(--v4-field-nested);
  padding-block: 0;
  padding-inline-start: calc(var(--v4-field-inline) - var(--v4-space-control-slot-inset));
  border: 0;
  background: transparent;
  box-shadow: none;
}
.triggerValue {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.triggerValue[data-placeholder] {
  color: var(--v4-muted);
}
.summary {
  display: flex;
  align-items: center;
  gap: var(--v4-space-6);
  min-width: 0;
}
.summary > span:first-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.more {
  font-family: var(--v4-type-mono-sm-font-family);
  font-size: var(--v4-type-mono-sm-font-size);
  line-height: var(--v4-type-mono-sm-line-height);
  font-weight: var(--v4-type-mono-sm-font-weight);
  letter-spacing: var(--v4-type-mono-sm-letter-spacing);
  flex: 0 0 auto;
  color: var(--v4-muted);
}

.chip {
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-weight: var(--v4-type-caption-font-weight);
  letter-spacing: var(--v4-type-caption-letter-spacing);
  display: inline-flex;
  align-items: center;
  gap: var(--v4-space-4);
  border: 1px solid var(--v4-line-soft, var(--border));
  background: var(--v4-tint);
  color: var(--v4-ink);
  padding: 2px 6px;
  min-width: 0;
  max-width: 100%;
  border-radius: 0;
}
.chip[data-locked] {
  background: transparent;
  color: var(--v4-muted);
}
.chip.mono {
  font-family: var(--v4-font-mono, monospace);
}
.chip > span:first-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.chip > [data-v4-button] {
  flex-shrink: 0;
}
.multiCombobox[data-size] {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--v4-space-control-slot-gap);
  padding-block: var(--v4-space-control-slot-inset);
  padding-inline: var(--v4-space-control-slot-inset) 0;
}
.multiCombobox > [data-slot="tags-input-input"] {
  flex: 1 1 120px;
  min-height: var(--v4-field-nested);
  padding-inline: calc(var(--v4-field-inline) - var(--v4-space-control-slot-inset))
    var(--v4-field-inline);
}
.multiCombobox > .chip {
  box-sizing: border-box;
  height: var(--v4-field-nested);
  padding-block: 0;
  padding-inline: calc(
      var(--v4-field-inline) - var(--v4-space-control-slot-inset) - var(--v4-size-control-border)
    )
    0;
}
.multiCombobox > [data-slot="combobox-clear"] {
  --v4-action-height: var(--v4-field-nested);
  margin-inline-end: var(--v4-space-control-slot-inset);
}
.multiCombobox > .chip > [data-v4-button] {
  --v4-action-height: calc(var(--v4-field-nested) - 2 * var(--v4-size-control-border));
}

.option[role="option"] {
  gap: var(--v4-space-10);
}
.optionLabel {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.optionMeta {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 50%;
  overflow: hidden;
  color: var(--v4-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-caption-letter-spacing);
}
.optionCheck {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
}
.optionCheck svg {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
}
.optionBox {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: calc(var(--v4-size-icon) + 2 * var(--v4-size-control-border));
  height: calc(var(--v4-size-icon) + 2 * var(--v4-size-control-border));
  border-radius: 0;
}
[aria-disabled="true"] > .optionBox {
  border-color: var(--v4-line-soft);
  background-color: var(--v4-line-soft);
  color: var(--v4-faint);
}
[aria-disabled="true"] > .optionBox[data-state="checked"] {
  border-color: var(--v4-control);
  background-color: var(--v4-control);
  color: var(--v4-surface);
}
.quickBar {
  box-sizing: content-box;
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--v4-space-2);
  height: var(--v4-size-control-md);
  padding-inline: var(--v4-space-10) var(--v4-space-4);
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.quickStatus {
  flex: 1 1 auto;
  min-width: 0;
  margin-inline-end: var(--v4-space-8);
  overflow: hidden;
  color: var(--v4-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-weight: var(--v4-type-caption-font-weight);
  letter-spacing: var(--v4-type-caption-letter-spacing);
}
.commandText {
  flex-direction: row;
  align-items: baseline;
  gap: var(--v4-space-8);
}
.commandText > :first-child {
  flex: none;
  max-width: 100%;
}
.pathAnchor {
  width: 100%;
  min-width: 0;
}
.pathList {
  width: var(--radix-popover-trigger-width);
}
